WITH parsed AS (SELECT id, currency, tier_limits, tier_prices, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, SLICE(tier_limits, 1, 2) AS first_two_limits, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers WHERE currency <> 'THB') SELECT currency, COUNT(*) AS event_count, APPROX_PERCENTILE(lowest_price, 0.5) AS lowest_price_p50, SUM(CASE WHEN currency = 'USD' THEN entry_price ELSE 0 END) AS usd_entry_price, COUNT(DISTINCT id) AS distinct_ids, COUNT_IF(currency = 'USD') AS usd_events, COUNT(CASE WHEN currency = 'USD' THEN 1 END) AS usd_count FROM parsed GROUP BY currency ORDER BY usd_events NULLS LAST
